```typescript
type FetchWithRetryOptions = RequestInit & {
  retries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
};

export async function fetchWithRetry(
  url: string,
  {
    retries = 3,
    baseDelayMs = 300,
    maxDelayMs = 10_000,
    ...init
  }: FetchWithRetryOptions = {}
): Promise<Response> {
  let lastError: unknown;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, init);

      // Retry on retryable status codes
      if (response.status >= 500 || response.status === 429) {
        if (attempt === retries) return response;
        lastError = new Error(`HTTP ${response.status}`);
      } else {
        return response;
      }
    } catch (error) {
      if (attempt === retries) throw error;
      lastError = error;
    }

    // Exponential backoff with jitter
    const delay = Math.min(
      baseDelayMs * 2 ** attempt,
      maxDelayMs
    );
    await new Promise((r) => setTimeout(r, delay + Math.random() * delay * 0.3));
  }

  throw lastError;
}
```

Usage:

```typescript
const res = await fetchWithRetry("https://api.example.com/data", {
  retries: 5,
  headers: { Authorization: "Bearer token" },
});
```

Notes:
- Retries on network errors, 5xx, and 429 responses
- Jitter (±30%) prevents thundering-herd issues
- Honors `Retry-After`? Not shown — add it if needed by parsing `response.headers.get("Retry-After")`

A 415 means the server doesn't accept the `Content-Type` header your request is sending. Common causes:

**1. Missing or wrong Content-Type header**
```js
// Wrong - server may default to text/plain
fetch('/api/endpoint', { method: 'POST', body: someData });

// Right for JSON
fetch('/api/endpoint', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(someData)
});
```

**2. Sending JSON but header says something else** (or vice versa) — the header must match the actual body format.

**3. Sending an object instead of a string**
```js
body: { name: 'x' }        // becomes "[object Object]"
body: JSON.stringify(data) // correct
```

**4. Using FormData** — don't set Content-Type manually; the browser sets it with the correct boundary:
```js
const fd = new FormData();
fd.append('file', fileInput.files[0]);
fetch('/upload', { method: 'POST', body: fd }); // no Content-Type header!
```

**5. Server-side mismatch** — e.g., a Spring `@RequestBody` expects JSON but you sent `text/plain`, or an ASP.NET `[FromBody]` binding requires `application/json`.

**Quick debug:** check the actual request headers in your browser's Network tab (or curl `-v`) and confirm the `Content-Type` matches what the endpoint accepts.

```typescript
type AsyncFunction<A extends unknown[], R> = (...args: A) => Promise<R>;

export function debounceAsync<A extends unknown[], R>(
  fn: AsyncFunction<A, R>,
  delay: number
): AsyncFunction<A, R> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let pending: {
    resolve: (value: R) => void;
    reject: (reason: unknown) => void;
  }[] = [];

  return (...args: A): Promise<R> => {
    if (timer) clearTimeout(timer);

    const promise = new Promise<R>((resolve, reject) => {
      pending.push({ resolve, reject });
    });

    timer = setTimeout(async () => {
      const waiters = pending;
      pending = [];
      try {
        const result = await fn(...args);
        waiters.forEach(w => w.resolve(result));
      } catch (err) {
        waiters.forEach(w => w.reject(err));
      }
    }, delay);

    return promise;
  };
}
```

Usage:

```typescript
const search = debounceAsync(async (q: string) => {
  const res = await fetch(`/api/search?q=${q}`);
  return res.json();
}, 300);

// All calls within 300ms share the final result
const results = await search("hello");
```

Key behaviors:
- **All callers get a promise** — even superseded calls resolve (with the latest result) instead of hanging.
- **Errors propagate** to every pending caller.
- **Generic types** preserve the original function's parameter and return types.

