```python
import time
import random
import functools

def retry_with_backoff(max_retries=5, base_delay=1.0, max_delay=60.0, exceptions=(Exception,)):
    """Retry decorator with exponential backoff and jitter."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    if attempt == max_retries:
                        raise
                    delay = min(base_delay * (2 ** attempt), max_delay)
                    # full jitter to avoid thundering herd
                    sleep_time = random.uniform(0, delay)
                    print(f"Attempt {attempt + 1} failed: {e}. Retrying in {sleep_time:.2f}s")
                    time.sleep(sleep_time)
        return wrapper
    return decorator

# Usage
@retry_with_backoff(max_retries=5, base_delay=1.0, exceptions=(ConnectionError, TimeoutError))
def call_flaky_api():
    import requests
    resp = requests.get("https://api.example.com/data", timeout=10)
    resp.raise_for_status()
    return resp.json()
```

Key points:
- **Exponential backoff**: delay doubles each attempt (1s, 2s, 4s, 8s...)
- **Jitter**: randomizes sleep time to prevent synchronized retries
- **`max_delay`**: caps the wait time
- **`exceptions`**: only retries on the errors you specify — don't catch everything blindly
- Raises the last exception after exhausting retries

