```js
function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null)
    return a === b;

  if (Array.isArray(a) !== Array.isArray(b)) return false;

  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    return a.every((item, i) => deepEqual(item, b[i]));
  }

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;

  return keysA.every(
    (key) => Object.prototype.hasOwnProperty.call(b, key) && deepEqual(a[key], b[key])
  );
}

// Usage
const arr1 = [{ id: 1, name: "Alice" }, { id: 2, name: "Bob" }];
const arr2 = [{ name: "Alice", id: 1 }, { name: "Bob", id: 2 }];

console.log(deepEqual(arr1, arr2)); // true
```

Key order is ignored because `Object.keys` comparison is done via `hasOwnProperty` lookup, not positional matching.

**Alternative (JSON hack, works for JSON-safe data only):**

```js
const normalize = (arr) =>
  JSON.stringify([...arr].map(o =>
    Object.keys(o).sort().reduce((acc, k) => ({ ...acc, [k]: o[k] }), {})
  ));

console.log(normalize(arr1) === normalize(arr2)); // true
```

Note: the JSON hack fails on `undefined`, `Date`, `NaN`, and functions — prefer `deepEqual`.

```typescript
type DeepReadonly<T> = {
  readonly [K in keyof T]: T[K] extends object
    ? T[K] extends Function
      ? T[K]
      : DeepReadonly<T[K]>
    : T[K];
};

// Usage
const config = {
  host: "localhost",
  port: 8080,
  options: {
    debug: true,
    retries: 3,
  },
} as const satisfies Record<string, unknown>;

type Config = DeepReadonly<typeof config>;
```

Notes:
- `DeepReadonly` recursively makes every property `readonly`.
- The `Function` check prevents mangling method signatures (functions aren't wrapped).
- If your config contains arrays or Maps/Sets and you want them readonly too, use this extended version:

```typescript
type DeepReadonly<T> = T extends (...args: never[]) => unknown
  ? T
  : T extends readonly unknown[]
    ? readonly DeepReadonly<T[number]>[]
    : T extends Map<infer K, infer V>
      ? ReadonlyMap<DeepReadonly<K>, DeepReadonly<V>>
      : T extends Set<infer V>
        ? ReadonlySet<DeepReadonly<V>>
        : T extends object
          ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
          : T;
```

