Write a recursive comparison:

```js
function deepEqual(a, b) {
  if (a === b) return true;

  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null)
    return false;

  if (Array.isArray(a) !== Array.isArray(b)) return false;

  if (a instanceof Date && b instanceof Date)
    return a.getTime() === b.getTime();

  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) return false;

  return keysA.every(
    (key) => Object.hasOwn(b, key) && deepEqual(a[key], b[key])
  );
}
```

Usage:

```js
deepEqual({ a: 1, b: [2, 3] }, { b: [2, 3], a: 1 }); // true
deepEqual({ a: 1 }, { a: 2 }); // false
```

Notes:
- `a === b` first handles primitives and identical references.
- Key length check + `Object.hasOwn` catches missing/extra keys.
- Add `Number.isNaN(a) && Number.isNaN(b)` if you need NaN to equal NaN.

For production, consider a battle-tested library instead: Lodash's `_.isEqual(a, b)` or `fast-deep-equal` on npm.

The most common cause: **esbuild only applies the `jsx` option to files loaded with a JSX-capable loader** (`.jsx`/`.tsx`). Plain `.js` files use the `js` loader, which doesn't parse JSX at all — so the option appears "ignored."

Fix by telling esbuild to treat `.js` as JSX:

```js
// esbuild.config.js
const esbuild = require("esbuild");

esbuild.build({
  entryPoints: ["src/index.js"],
  bundle: true,
  outdir: "dist",
  jsx: "automatic",          // or "transform" / "preserve"
  loader: { ".js": "jsx" },   // <-- this is what you're probably missing
});
```

