You can cover most cases with a small middleware that trims, strips HTML, and caps lengths — no dependencies needed:

```js
// sanitize.js
const stripTags = (str) => str.replace(/<[^>]*>/g, '');

const clean = (value, maxLen = 1000) => {
  if (typeof value === 'string') {
    return stripTags(value.trim()).slice(0, maxLen);
  }
  if (Array.isArray(value)) return value.map((v) => clean(v, maxLen));
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, clean(v, maxLen)])
    );
  }
  return value;
};

module.exports = function sanitize(req, _res, next) {
  if (req.body) req.body = clean(req.body);
  if (req.query) req.query = clean(req.query);
  // params are usually safe route segments, but you can clean them too
  next();
};
```

Usage:

```js
app.use(express.json());
app.use(require('./sanitize'));
```

Key points:

- **Validation is separate from sanitization** — still check types, formats, and ranges explicitly (e.g., `typeof req.body.email === 'string'`).
- **Don't rely on this for security** — real protection against XSS is escaping on *output* (frontend frameworks do this by default), and against SQL injection is parameterized queries.
- If you need proper HTML *escaping* (not stripping), the `escape-html` package is ~1KB and battle-tested.
- For deeply nested or hostile payloads, consider `JSON.parse` limits via `express.json({ limit: '10kb' })` to start with.

