```typescript
function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  delay: number
): (...args: A) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;

  return (...args: A) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}
```

Usage:

```typescript
const log = debounce((message: string, count: number) => {
  console.log(message, count);
}, 300);

log("hello", 1);
log("hello", 2); // only this call runs after 300ms
```

The `A extends unknown[]` generic preserves the exact parameter types of the wrapped function, so `log` is correctly typed as `(message: string, count: number) => void`.

If you also want a `cancel` method:

```typescript
function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  delay: number
) {
  let timer: ReturnType<typeof setTimeout> | undefined;

  const debounced = (...args: A) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };

  debounced.cancel = () => clearTimeout(timer);
  return debounced;
}
```

