```typescript
async function retry<T>(
  fn: () => Promise<T>,
  options: {
    retries?: number;
    baseDelayMs?: number;
    maxDelayMs?: number;
    factor?: number;
    onRetry?: (error: unknown, attempt: number) => void;
  } = {}
): Promise<T> {
  const {
    retries = 3,
    baseDelayMs = 200,
    maxDelayMs = 10_000,
    factor = 2,
    onRetry,
  } = options;

  let lastError: unknown;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === retries) break;

      const delay = Math.min(baseDelayMs * factor ** attempt, maxDelayMs);
      const jitter = Math.random() * delay * 0.3; // 30% jitter
      onRetry?.(error, attempt + 1);
      await new Promise((r) => setTimeout(r, delay + jitter));
    }
  }

  throw lastError;
}
```

Usage:

```typescript
const data = await retry(() => fetch("/api/data").then((r) => {
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return r.json();
}), { retries: 5, baseDelayMs: 500 });

// With a retry logger
await retry(fn, { onRetry: (err, n) => console.warn(`Attempt ${n} failed:`, err) });
```

Key features: exponential delay (`base * factor^attempt`), capped at `maxDelayMs`, jitter to avoid thundering herd, and an `onRetry` hook for logging/metrics.

```js
function throttle(fn, wait, { leading = true, trailing = true } = {}) {
  let lastArgs = null;
  let lastCallTime = 0;
  let timer = null;

  function invoke(context, args) {
    fn.apply(context, args);
    lastCallTime = Date.now();
    lastArgs = null;
  }

  return function throttled(...args) {
    const now = Date.now();
    const remaining = wait - (now - lastCallTime);

    if (remaining <= 0 || remaining > wait) {
      // Time window elapsed
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      if (leading || lastArgs) {
        invoke(this, leading && !lastArgs ? args : lastArgs);
      }
    } else {
      // Within window — save args for trailing call
      lastArgs = args;
      if (!timer && trailing) {
        timer = setTimeout(() => {
          timer = null;
          if (lastArgs) invoke(this, lastArgs);
        }, remaining);
      }
    }
  };
}
```

Usage:

```js
const onScroll = throttle(() => console.log("scroll"), 200);

// Leading only (fire immediately, ignore rest):
throttle(fn, 200, { trailing: false });

// Trailing only (wait until calls stop):
throttle(fn, 200, { leading: false });
```

- **leading**: fires on the first call in a window.
- **trailing**: fires once more with the latest args after the window ends, if calls occurred during it.

