Native, handles `Date`, `Map`, `Set`, `RegExp`, `ArrayBuffer`, circular references, etc. Available in all modern browsers, Node 17+, and Deno.

If you need to support older environments:

```js
function deepClone(obj, seen = new WeakMap()) {
  if (obj === null || typeof obj !== "object") return obj;
  if (seen.has(obj)) return seen.get(obj);

  if (obj instanceof Date) return new Date(obj);
  if (obj instanceof RegExp) return new RegExp(obj.source, obj.flags);
  if (obj instanceof Map) {
    const map = new Map();
    seen.set(obj, map);
    for (const [k, v] of obj) map.set(deepClone(k, seen), deepClone(v, seen));
    return map;
  }
  if (obj instanceof Set) {
    const set = new Set();
    seen.set(obj, set);
    for (const v of obj) set.add(deepClone(v, seen));
    return set;
  }

  const out = Array.isArray(obj) ? [] : {};
  seen.set(obj, out);
  for (const key of Reflect.ownKeys(obj)) {
    out[key] = deepClone(obj[key], seen);
  }
  return out;
}
```

Note: neither approach clones functions or DOM nodes — those are shared by reference.

Use `re.sub` with a replacement function and a counter:

```python
import re

def replace_nth(text, pattern, repl, n):
    count = 0
    def match_replace(m):
        nonlocal count
        count += 1
        return repl if count == n else m.group(0)
    return re.sub(pattern, match_replace, text)

text = "a-b-c-d"
print(replace_nth(text, "-", "X", 2))  # a-bXc-d
```

For a plain substring (no regex), split and rejoin:

```python
def replace_nth_sub(text, old, new, n):
    parts = text.split(old)
    if n >= len(parts):
        return text
    return old.join(parts[:n]) + new + old.join(parts[n:])
```

Both handle the general case; the regex version also works with patterns like `\d+` or groups.

Promises only resolve with **one value**, so you need to collect the callback's multiple arguments into an array or object:

```js
const { promisify } = require('util');

// Manual approach
function getUser(id) {
  return new Promise((resolve, reject) => {
    fetchUser(id, (err, name, email, age) => {
      if (err) return reject(err);
      resolve({ name, email, age }); // or [name, email, age]
    });
  });
}
```

If the API follows the Node convention (error-first, single result), `util.promisify` works out of the box:

```js
const fs = require('fs');
const readFile = promisify(fs.readFile); // resolves with the single data arg
```

For multi-arg callbacks, you can also write a generic helper:

```js
function promisifyMulti(fn, ctx) {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn.call(ctx, ...args, (err, ...results) => {
        if (err) reject(err);
        else resolve(results.length <= 1 ? results[0] : results);
      });
    });
}

// usage
const multiCb = promisifyMulti(callbackApi);
const [a, b, c] = await multiCb(input);
```

Tip: prefer resolving with an **object** (`{ name, email, age }`) over an array — it's self-documenting and order-independent.

```typescript
function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  delay: number
): (...args: A) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;

  return (...args: A) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}
```

Usage — parameter types are fully preserved:

```typescript
const log = debounce((message: string, count: number) => {
  console.log(message.repeat(count));
}, 300);

log("hi", 3);        // ✅
log("hi", "3");      // ❌ compile error
```

If you need the return value too, use a `Promise`-based version:

```typescript
function debounceAsync<A extends unknown[], R>(
  fn: (...args: A) => R,
  delay: number
): (...args: A) => Promise<R> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let rejectPrev: ((reason?: unknown) => void) | undefined;

  return (...args: A) =>
    new Promise<R>((resolve, reject) => {
      clearTimeout(timer);
      rejectPrev?.("debounced");
      rejectPrev = reject;
      timer = setTimeout(() => resolve(fn(...args)), delay);
    });
}
```

The key trick is `A extends unknown[]` — it captures the full parameter tuple, so each argument keeps its individual type instead of collapsing to a union.

That error usually comes from a `try/catch` that only logs the message. Log the full stack instead:

```js
try {
  someFunction();
} catch (e) {
  console.error(e.stack);   // full stack trace
  // or: console.error(e);  // most consoles print the trace too
}
```

Other tips:

- **Don't swallow errors** — `catch (e) {}` or `catch (e) { alert(e.message) }` hides the trace.
- **Use the debugger**: in Chrome DevTools, enable the pause icon with "Pause on exceptions" (and "Pause on caught exceptions"). It stops exactly where the error is thrown, with a full call stack in the right panel.
- **Unminified code / sourcemaps**: minified bundles produce useless traces. Build with `--source-map` (or `devtool: 'source-map'` in Webpack) so traces map back to readable source.
- **Node.js**: run with `node --stack-trace-limit=50` or set `Error.stackTraceLimit = 50;` if the trace is truncated.

The root cause is calling something that doesn't exist, e.g. `obj.method()` where `obj.method` is `undefined` — the stack trace will show you *which* object/call site.

